from datetime import datetime
from uuid import UUID, uuid4

from sqlalchemy import CheckConstraint, DateTime, Float, ForeignKey, Index, String, Uuid, func
from sqlalchemy.orm import Mapped, mapped_column

from app.db.base import Base
from app.models.workout import utcnow


class BodyWeight(Base):
    """One weigh-in. The id is generated by the client (logged offline too);
    the weight is stored as entered, in `unit`."""

    __tablename__ = "body_weights"
    __table_args__ = (
        CheckConstraint("unit IN ('kg', 'lb')", name="body_weights_unit_check"),
        Index("ix_body_weights_user_measured", "user_id", "measured_at"),
    )

    id: Mapped[UUID] = mapped_column(Uuid, primary_key=True, default=uuid4)
    user_id: Mapped[int] = mapped_column(ForeignKey("users.id", ondelete="CASCADE"))
    measured_at: Mapped[datetime] = mapped_column(DateTime(timezone=True))
    weight: Mapped[float] = mapped_column(Float)
    unit: Mapped[str] = mapped_column(String(2))
    # Percent, when the scale (or a caliper) tells.
    body_fat: Mapped[float | None] = mapped_column(Float)
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), default=utcnow, server_default=func.now()
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), default=utcnow, server_default=func.now()
    )
